function formatOutputTokensPerSecond(
  log: OutputTokensPerSecondInput,
): string | null {
  const tps = getOutputTokensPerSecond(log);
  if (tps == null) return null;
  return tps >= 1 ? Math.round(tps).toString() : tps.toFixed(1);
}

