function useLastValidValue<T>(value: T | null | undefined): T | null {
  const ref = useRef<T | null>(null);

  // 同步更新 ref（在渲染期间，不在 useEffect 中）
  if (value != null) {
    ref.current = value;
  }

  // 返回当前值或最后有效值
  return value ?? ref.current;
}

src/hooks/useLatestRef.ts::useLatestRef.source_code:
function useLatestRef<T>(value: T) {
  const ref = useRef(value);
  useEffect(() => {
    ref.current = value;
  }, [value]);
  return ref;
}

src/hooks/useLatestRef.ts::useCommittabl.source_code:
function useCommittableRef<T>(value: T, onChange: (next: T) => void) {
  const ref = useLatestRef(value);
  const onChangeRef = useLatestRef(onChange);
  const commit = useCallback(
    (next: T) => {
      ref.current = next;
      onChangeRef.current(next);
    },
    [ref, onChangeRef],
  );
  return [ref, commit] as const;
}

