src/hooks/useStackModelsChangedHint.ts::.source_code:
function publishedSignature(stack: ProxyStack): string {
  const ids = new Set(stack.members.flatMap((member) => member.modelIds));
  return [...ids].sort().join("\n");
}

function useStackModelsChangedHint(
  appId: string,
  stack: ProxyStack | undefined,
  updatedAt: number,
): () => void {
  const { t } = useTranslation();
  const baseline = useRef<string | null>(null);
  const skipNext = useRef(false);
  const signature =
    appId === "claude" && stack?.active ? publishedSignature(stack) : null;

  useEffect(() => {
    if (signature === null) {
      baseline.current = null;
      skipNext.current = false;
      return;
    }
    const previous = baseline.current;
    baseline.current = signature;
    if (skipNext.current) {
      skipNext.current = false;
      return;
    }
    if (previous !== null && previous !== signature) {
      toast.info(
        t("provider.stackModelsChanged", { client: getAppLabel(appId) }),
        { closeButton: true },
      );
    }
    // `t` 不在依赖里：切换语言不是一次重查，不能消费「跳过」。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [appId, signature, updatedAt]);

  return useCallback(() => {
    skipNext.current = true;
  }, []);
}

src/hooks/useStreamCheck.ts::useStreamCh.source_code:
function useStreamCheck(appId: AppId) {
  const { t } = useTranslation();
  const [checkingIds, setCheckingIds] = useState<Set<string>>(new Set());

  const checkProvider = useCallback(
    async (
      providerId: string,
      providerName: string,
    ): Promise<StreamCheckResult | null> => {
      setCheckingIds((prev) => new Set(prev).add(providerId));

      try {
        const result = await streamCheckProvider(appId, providerId);

        if (result.status === "operational") {
          toast.success(
            t("streamCheck.reachable", {
              providerName: providerName,
              responseTimeMs: result.responseTimeMs,
              defaultValue: `${providerName} 连通正常 (${result.responseTimeMs}ms)`,
            }),
            { closeButton: true },
          );
        } else if (result.status === "degraded") {
          toast.warning(
            t("streamCheck.reachableSlow", {
              providerName: providerName,
              responseTimeMs: result.responseTimeMs,
              defaultValue: `${providerName} 连通但较慢 (${result.responseTimeMs}ms)`,
            }),
          );
        } else {
          // 仅当无法建立连接（DNS / 连接被拒 / TLS / 超时）才会到这里
          toast.error(
            t("streamCheck.unreachable", {
              providerName: providerName,
              message: result.message,
              defaultValue: `${providerName} 无法连通: ${result.message}`,
            }),
            {
              description: t("streamCheck.unreachableHint", {
                defaultValue:
                  "无法建立连接（DNS / 连接 / TLS / 超时）。请检查 base_url 与网络。",
              }),
              duration: 8000,
              closeButton: true,
            },
          );
        }

        return result;
      } catch (e) {
        toast.error(
          t("streamCheck.error", {
            providerName: providerName,
            error: String(e),
            defaultValue: `${providerName} 检查出错: ${String(e)}`,
          }),
        );
        return null;
      } finally {
        setCheckingIds((prev) => {
          const next = new Set(prev);
          next.delete(providerId);
          return next;
        });
      }
    },
    [appId, t],
  );

  const isChecking = useCallback(
    (providerId: string) => checkingIds.has(providerId),
    [checkingIds],
  );

  return { checkProvider, isChecking };
}

src/hooks/useTauriEvent.ts::useTauriEven.source_code:
function useTauriEvent<P>(
  eventName: string,
  handler: (payload: P) => void | Promise<void>,
): void {
  const handlerRef = useRef(handler);
  handlerRef.current = handler;

  useEffect(() => {
    let disposed = false;
    let unlisten: UnlistenFn | undefined;

    void (async () => {
      try {
        const off = await listen<P>(eventName, (event) => {
          void handlerRef.current(event.payload);
        });
        if (disposed) {
          off();
        } else {
          unlisten = off;
        }
      } catch (error) {
        console.error(`Failed to subscribe ${eventName} event`, error);
      }
    })();

    return () => {
      disposed = true;
      unlisten?.();
    };
  }, [eventName]);
}

