function matchEndpoint<T>(
  baseUrl: string,
  candidates: readonly T[],
  endpointOf: (candidate: T) => string | null,
): T[] {
  const target = endpointKey(baseUrl);
  if (!target) return [];
  return candidates.filter((candidate) => endpointOf(candidate) === target);
}

